#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;
constexpr int32_t CMP_BUF_FACTOR = 2;

template <typename T>
class KernelLessEqual {
public:
    __aicore__ inline KernelLessEqual() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
            zGm.SetGlobalBuffer((__gm__ uint8_t *)z + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
            zGm.SetGlobalBuffer((__gm__ uint8_t *)z + offset, tailLength);
        }

        this->tileLength = tileLength;

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueY, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(cmpBuf, static_cast<uint32_t>((tileLength + 7) / 8 * CMP_BUF_FACTOR));
        pipe.InitBuffer(outQueueZ, BUFFER_NUM, tileLength * sizeof(uint8_t));
    }

    __aicore__ inline void Process()
    {
        int64_t cmpAlign = 256 / static_cast<int64_t>(sizeof(T));
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        if (tailTileLength > 0 && (tailTileLength % cmpAlign) != 0) {
            int64_t alignedTailLen = ((tailTileLength + cmpAlign - 1) / cmpAlign) * cmpAlign;

            for (int64_t i = 0; i < tileNum - 1; ++i) {
                CopyIn(i, this->tileLength, this->tileLength);
                Compute(i, this->tileLength, this->tileLength);
                CopyOut(i, this->tileLength);
            }
            if (tileNum > 0) {
                CopyIn(tileNum - 1, alignedTailLen, tailTileLength);
                Compute(tileNum - 1, alignedTailLen, tailTileLength);
                CopyOut(tileNum - 1, tailTileLength);
            }
        } else {
            for (int64_t i = 0; i < tileNum - 1; ++i) {
                CopyIn(i, this->tileLength, this->tileLength);
                Compute(i, this->tileLength, this->tileLength);
                CopyOut(i, this->tileLength);
            }
            if (tileNum > 0) {
                CopyIn(tileNum - 1, tailTileLength, tailTileLength);
                Compute(tileNum - 1, tailTileLength, tailTileLength);
                CopyOut(tileNum - 1, tailTileLength);
            }
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength, int64_t validLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        AscendC::LocalTensor<T> yLocal = inQueueY.AllocTensor<T>();

        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(validLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParams, padParams);
        AscendC::DataCopyPad(yLocal, yGm[progress * this->tileLength], copyParams, padParams);

        if (curTileLength > validLength) {
            int64_t cmpAlign = 256 / static_cast<int64_t>(sizeof(T));
            int64_t padCount = curTileLength - validLength;
            AscendC::Duplicate(xLocal[validLength], T(0), static_cast<uint32_t>(padCount));
            AscendC::Duplicate(yLocal[validLength], T(0), static_cast<uint32_t>(padCount));
        }

        inQueueX.EnQue(xLocal);
        inQueueY.EnQue(yLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength, int64_t validLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
        AscendC::LocalTensor<T> yLocal = inQueueY.DeQue<T>();
        AscendC::LocalTensor<uint8_t> cmpLocal = cmpBuf.Get<uint8_t>();
        AscendC::LocalTensor<uint8_t> outLocal = outQueueZ.AllocTensor<uint8_t>();

        AscendC::Compare(cmpLocal, xLocal, yLocal, AscendC::CMPMODE::LE,
                         static_cast<uint32_t>(curTileLength));

        int64_t packedBytes = static_cast<int64_t>((curTileLength + 7) / 8);
        for (int64_t j = 0; j < packedBytes; ++j) {
            uint8_t byteVal = cmpLocal.GetValue(j);
            int64_t baseIdx = j * 8;
            for (int32_t bit = 0; bit < 8 && (baseIdx + bit) < validLength; ++bit) {
                outLocal.SetValue(baseIdx + bit, (byteVal >> bit) & 0x01);
            }
        }

        outQueueZ.EnQue<uint8_t>(outLocal);
        inQueueX.FreeTensor(xLocal);
        inQueueY.FreeTensor(yLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<uint8_t> outLocal = outQueueZ.DeQue<uint8_t>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(uint8_t)), 0, 0, 0};
        AscendC::DataCopyPad(zGm[progress * this->tileLength], outLocal, copyParams);
        outQueueZ.FreeTensor(outLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueY;
    AscendC::TBuf<AscendC::TPosition::VECCALC> cmpBuf;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueZ;
    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<T> yGm;
    AscendC::GlobalTensor<uint8_t> zGm;
    int64_t blockLength;
    int64_t tileLength;
};

extern "C" __global__ __aicore__ void less_equal(GM_ADDR x, GM_ADDR y, GM_ADDR z,
                                                  int64_t formerNum, int64_t formerLength,
                                                  int64_t tailLength, int64_t tileLength,
                                                  int64_t dtypeSize)
{
    if (dtypeSize == 2) {
        KernelLessEqual<half> op;
        op.Init(x, y, z, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else {
        KernelLessEqual<float> op;
        op.Init(x, y, z, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    }
}
